import{_ as t,a as o,o as r,a6 as a}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse(`{"title":"Export Orders","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-orders-export","title":"Export Orders (CSV)","description":"Download the orders datagrid as a CSV file — the same data the admin Orders \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/orders/export?format=csv\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: text/csv\\" \\\\\\n  --output orders.csv\\n","response":"# Binary response: a text/csv attachment is written to orders.csv\\n# (Content-Disposition: attachment; filename=\\"orders.csv\\"). Sample contents:\\n\\nID,Status,\\"Grand Total\\",\\"Payment Method\\",Channel,Customer,Email,\\"Order Date\\"\\n2413,processing,$554.00,\\"Money Transfer\\",\\"Default Channel\\",\\"John Doe\\",john@example.com,\\"2026-06-04 18:34:43\\"\\n"},{"id":"admin-orders-export-xlsx","title":"Export Orders (XLSX)","description":"Download the orders datagrid as an XLSX file — the same data the admin Orders \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/orders/export?format=xlsx\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\" \\\\\\n  --output orders.xlsx\\n","response":"# Binary response: an XLSX workbook is written to disk\\n# (Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\n#  Content-Disposition: attachment; filename=\\"orders.xlsx\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"},{"id":"admin-orders-export-xls","title":"Export Orders (XLS)","description":"Download the orders datagrid as an XLS file — the same data the admin Orders \\"Export\\" button produces. Honours the same filters as the listing.","query":"curl -X GET \\"https://your-domain.com/api/admin/orders/export?format=xls\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/vnd.ms-excel\\" \\\\\\n  --output orders.xls\\n","response":"# Binary response: an XLS workbook is written to disk\\n# (Content-Type: application/vnd.ms-excel\\n#  Content-Disposition: attachment; filename=\\"orders.xls\\").\\n# Same columns as the CSV export, as the first sheet's header row plus one row per record.\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/sales/orders/export.md","filePath":"api/rest-api/admin/sales/orders/export.md","lastUpdated":1786429091000}`),d={name:"api/rest-api/admin/sales/orders/export.md"};function s(n,e,i,c,p,l){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="export-orders" tabindex="-1">Export Orders <a class="header-anchor" href="#export-orders" aria-label="Permalink to &quot;Export Orders&quot;">​</a></h1><p>Downloads the orders datagrid as a <strong>csv, xls or xlsx file</strong> — the same data the admin <strong>Sales → Orders</strong> &quot;Export&quot; button produces. The response is a binary file attachment, not JSON. Requires the <code>sales.orders.view</code> permission.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/orders/export</code></td><td>GET</td></tr></tbody></table><h2 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h2><p>The export carries the eight datagrid columns, in order:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>ID</code></td><td>Order number.</td></tr><tr><td><code>Status</code></td><td>The order status (e.g. <code>processing</code>, <code>completed</code>).</td></tr><tr><td><code>Grand Total</code></td><td>The order&#39;s total, in the store&#39;s base currency, formatted (e.g. <code>$554.00</code>).</td></tr><tr><td><code>Payment Method</code></td><td>The payment method used (e.g. <code>Money Transfer</code>).</td></tr><tr><td><code>Channel</code></td><td>The channel the order was placed on.</td></tr><tr><td><code>Customer</code></td><td>The customer&#39;s name.</td></tr><tr><td><code>Email</code></td><td>The customer&#39;s email.</td></tr><tr><td><code>Order Date</code></td><td>When the order was placed.</td></tr></tbody></table><h2 id="query-parameters" tabindex="-1">Query parameters <a class="header-anchor" href="#query-parameters" aria-label="Permalink to &quot;Query parameters&quot;">​</a></h2><p><code>format</code> selects the export format — <code>csv</code> (the default), <code>xls</code> or <code>xlsx</code>; any other value returns <code>422</code>. Send an <code>Accept</code> header matching the format: <code>text/csv</code>, <code>application/vnd.ms-excel</code> or <code>application/vnd.openxmlformats-officedocument.spreadsheetml.sheet</code>.</p><p>The export honours the <strong>same filters as the <a href="/api/rest-api/admin/sales/orders/list-orders.html">listing</a></strong>, so you export exactly the rows you&#39;re viewing: <code>order_id</code>, <code>status</code>, <code>grand_total</code> (plus the <code>grand_total_from</code> / <code>_to</code> range), <code>channel</code>, <code>customer</code>, <code>email</code>, plus the date presets (<code>today</code>, <code>yesterday</code>, <code>this_week</code>, <code>this_month</code>, <code>last_month</code>, <code>last_three_months</code>, <code>last_six_months</code>, <code>this_year</code>) and custom <code>date_from</code> / <code>date_to</code>. (Pagination does not apply — the export returns every matching row.)</p><h2 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h2><p><code>sales.orders.view</code></p>',12)]))}const u=t(d,[["render",s]]);export{m as __pageData,u as default};
